$(function(){function format(state){if(!state.id)return state.text;return state.text;}
window.previous_template='';function update_language_template(){var source=$('textarea#id_source');if(source.val()==window.previous_template.replace(/\r/g,'')||source.val()==''){var lang_id=$('#id_language').val();var code=localStorage.getItem('submit:'+$('#id_language').val());function update_submit_area(code){window.previous_template=code;source.val(code);window.ace_source.getSession().setValue(code);}
if(code!=null){update_submit_area(code);}else{$.get('/widgets/template',{id:lang_id}).done(function(template){update_submit_area(template);});}}}
function makeDisplayData(data){var site_data=data.attr('data-info');var judge_data=data.attr('data-judge-info');var display_data=site_data||judge_data;return display_data;}
function formatSelection(state){if(!state.id)return state.text;var data=makeDisplayData($("option[data-id="+state.id+"]"));return $('<span>').append($('<b>').text(state.text),' (',data,')');}
$("#id_language").select2({templateResult:format,templateSelection:formatSelection,dropdownParent:$('#language-select')});if($('#id_judge').is('select')){$("#id_judge").select2({dropdownParent:$('#judge-select')});}
$('#id_language').on('select2:open',function(evt){var dropdown=$('.select2-dropdown');if(!$('#result-version-info').length)
dropdown.append($("<span id=\"result-version-info\">"));dropdown.attr('id','language-select2');});if($('#id_judge').is('select')){$('#id_judge').on('select2:open',function(evt){var dropdown=$('.select2-dropdown');$('#result-version-info').remove();dropdown.attr('id','judge-select2');});}
$('#id_language').change(function(){var lang=$("#id_language").find("option:selected").attr('data-ace');window.ace_source.getSession().setMode("ace/mode/"+lang);update_language_template();});$('#ace_source').on('ace_load',function(e,editor){update_language_template();editor.commands.addCommand({name:'save',bindKey:{win:'Ctrl-S',mac:'Command-S'},exec:function(){localStorage.setItem('submit:'+$('#id_language').val(),editor.getSession().getValue());}});editor.getSession().setUseWrapMode(true);editor.setFontSize(14);editor.setPrintMarginColumn(100);editor.focus();});$(window).resize(function(){$('#ace_source').height(Math.max($(window).height()-353,100));}).resize();$('.problem_submit').submit(function(event){if($('#id_source').val().length>65536){alert("Mã nguồn của bạn chỉ được chứa tối đa 65536 kí tự.");event.preventDefault();$('.problem_submit').find(':submit').attr('disabled',false);}});function on_language_change(){obj=document.getElementById('id_language');fileonly=obj.options[obj.selectedIndex].getAttribute('data-fileonly');if(fileonly=='True'){if(!$('#editor').hasClass('hidden')){$('#editor').addClass('hidden');}
if($('#file-submit').hasClass('hidden')){$('#file-submit').removeClass('hidden');}
file_ext='.'+obj.options[obj.selectedIndex].getAttribute('data-ext');file_size_limit=obj.options[obj.selectedIndex].getAttribute('data-file-size');$('#file_upload').val('');$('#file_upload').attr({accept:file_ext});$('#file_drag').html('<b>'+'Nhấp để chọn tệp hoặc kéo tệp vào hộp này'+'</b><br>'+`Chỉ chấp nhận "${file_ext}". Kích thước tệp tối đa là ${file_size_limit}MB.`);}else{if($('#editor').hasClass('hidden')){$('#editor').removeClass('hidden');}
if(!$('#file-submit').hasClass('hidden')){$('#file-submit').addClass('hidden');}}};$("#id_language").change(function(){on_language_change();});on_language_change();function fileDragHover(e){e.stopPropagation();e.preventDefault();if(e.type==='dragover'){$('#file_drag').addClass('hover');}else{$('#file_drag').removeClass('hover');}}
function fileDropHandler(e){fileDragHover(e);$('#file_upload').prop('files',e.originalEvent.dataTransfer.files);handleFileChange()}
$('#file_drag').on('dragover',fileDragHover);$('#file_drag').on('dragleave',fileDragHover);$('#file_drag').on('drop',fileDropHandler);});function handleFileSelect(){var file=$('#file_select')[0].files[0];if(file&&window.FileReader){var reader=new FileReader();reader.onload=function(){ace_source.session.setValue(reader.result);if(file.name.search('.')!=-1){var ext=file.name.split('.').pop();var languages=$('#id_language')[0].options;for(var i=languages.length-1;i>=0;i--){if(languages[i].getAttribute('data-fileonly')==='False'&&languages[i].getAttribute('data-ext')===ext){$('#id_language').val(languages[i].value).change();break;}}}};reader.readAsText(file);}}
function handleFileChange(){var file=$('#file_upload')[0].files[0];if(file){$('#file_drag').html('<b>'+'Tên tệp'+':</b> '+file.name+'<br>'+'<b>'+'Kích thước tệp'+':</b> '+(file.size/(1024*1024)).toFixed(2)+' MB');}};